\begin{proof}
First, we show two key claims.

\begin{claim}\label{claim:Hadamard}
For any $S$ and $\Delta$, it holds that $H^{\otimes 2\secp+1}E_{\widehat{S},\widehat{\Delta}} = E_{S,\Delta}H$.
\end{claim}

\begin{proof}
We show that the maps are equivalent by checking their behavior on the basis $\{\ket{+},\ket{-}\}$. First, 

\begin{align*}
H^{\otimes 2\secp+1}E_{\widehat{S},\widehat{\Delta}}\ket{+} = H^{\otimes 2\secp+1}\ket*{\widehat{S}_{\widehat{\Delta}}} = \ket{S} = E_{S,\Delta}\ket{0} = E_{S,\Delta}H\ket{+}.
\end{align*}

Next, 
\begin{align*}
H^{\otimes 2\secp+1}E_{\widehat{S},\widehat{\Delta}}\ket{-} = H^{\otimes 2\secp+1}\left(\ket*{\widehat{S}} - \ket*{\widehat{S} + \widehat{\Delta}}\right)= H^{\otimes 2\secp + 1}Z^{\Delta}\ket*{\widehat{S}_{\widehat{\Delta}}} = \ket*{S+\Delta} = E_{S,\Delta}\ket{1} = E_{S,\Delta}H\ket{-}.
\end{align*}

\end{proof}

\begin{claim}\label{claim:linear}
For any $S,\Delta$, and $L$, $\LinEval_LE_{S,\Delta}^{\otimes n} = E_{S,\Delta}^{\otimes n}L$
\end{claim}

\begin{proof}
We show this for the case where $L$ contains a single CNOT gate, and the full proof follows by applying the argument sequentially. We show that the maps are equivalent by checking their behavior on the basis $\{\ket{b_1,b_2}\}_{b_1,b_2 \in \{0,1\}}$. 

\begingroup
\allowdisplaybreaks
\begin{align*}
&\mathsf{CNOT}^{\otimes 2\secp+1}E_{S,\Delta}^{\otimes 2}\ket{b_1,b_2}\\
&= \mathsf{CNOT}^{\otimes 2\secp+1}\ket{S+b_1 \cdot \Delta}\ket{S + b_2 \cdot \Delta}\\
&= \frac{1}{2^{\secp}}\mathsf{CNOT}^{\otimes 2\secp+1} \sum_{s_1 \in S}\ket{s_1 + b_1 \cdot \Delta}\sum_{s_2 \in S}\ket{s_2 + b_2 \cdot \Delta}\\
&= \frac{1}{2^{\secp}} \sum_{s_1 \in S}\ket{s_1 + b_1 \cdot \Delta}\sum_{s_2 \in S}\ket{(s_1 + s_2) + (b_1 + b_2) \cdot \Delta}\\
&= \ket{S+b_1 \cdot \Delta}\ket{S + (b_1 + b_2) \cdot \Delta}\\
&= E_{S,\Delta}^{\otimes 2}\mathsf{CNOT}\ket{b_1,b_2}.
\end{align*}
\endgroup

\end{proof}

Now, define measurements $M'_{\theta,f},\widetilde{M}'_{\theta,f,k,L}$ so that \[M_{\theta,f} = H^{\MS_1}M'_{\theta,f}H^{\MS_1}, ~~ \text{ and } ~~ \widetilde{M}_{\theta,f,k,L} = H^{\widetilde{\MS}_1}X^{x_{L,\MS_0},z_{L,\MS_1}}\widetilde{M}'_{\theta,f,k,L}X^{x_{L,\MS_0},z_{L,\MS_1}}H^{\widetilde{\MS}_1}.\] 

To be concrete,

\[M'_{\theta,f} \coloneqq \left\{\sum_{m : f(m_\MS) = y}\ketbra{m}{m}\right\}_{y},\] and \[\widetilde{M}'_{\theta,f,k,L} \coloneqq \left\{\sum_{m : f(m_\MS) = y}\left(\sum_{\substack{c : \{c_i \in S+m_i \cdot \Delta\}_{i \in \MS_0},\\ \{c_i \in \widehat{S}+m_i \cdot \widehat{\Delta}\}_{i \in \MS_1}}}\ketbra{c}{c}\right)\right\}_{y} \cup \left\{\sum_{\substack{c: \exists i \in \MS_0 \text{ s.t. } c_i \notin S_\Delta\\ \ \ \vee \exists i \in \MS_1 \text{ s.t. }c_i \notin \widehat{S}_{\widehat{\Delta}}}}\ketbra{c}{c}\right\}.\]

Observe that 

\[\widetilde{M}'_{\theta,f,k,L}\left(E_{S,\Delta}^{\otimes |\MS_\bot \cup \MS_0|} \otimes E_{\widehat{S},\widehat{\Delta}}^{\otimes |\MS_1|}\right) = \left(E_{S,\Delta}^{\otimes |\MS_\bot \cup \MS_0|} \otimes E_{\widehat{S},\widehat{\Delta}}^{\otimes |\MS_1|}\right)M'_{\theta,f}.\]

Then,

\begingroup
\allowdisplaybreaks
\begin{align*}
&\LinEval_L^\dagger\widetilde{M}_{\theta,f,k,L}\LinEval_L\Enc_k\\
&=\LinEval_L^\dagger\widetilde{M}_{\theta,f,k,L}\LinEval_L X^xZ^zE_{S,\Delta}^{\otimes n}  \\
&=\LinEval_L^\dagger\widetilde{M}_{\theta,f,k,L}X^{x_L}Z^{z_L} \LinEval_LE_{S,\Delta}^{\otimes n}\\
&=\LinEval_L^\dagger\widetilde{M}_{\theta,f,k,L}X^{x_L}Z^{z_L}E^{\otimes n}_{S,\Delta}L \tag{\cref{claim:linear}}\\
&=\LinEval_L^\dagger H^{\widetilde{\MS}_1}X^{x_{L,\MS_0}z_{L,\MS_1}}\widetilde{M}'_{\theta,f,k,L}X^{x_{L,\MS_0},z_{L,\MS_1}}H^{\widetilde{\MS}_1}X^{x_L}Z^{z_L}E^{\otimes n}_{S,\Delta}L\\
&=\LinEval_L^\dagger H^{\widetilde{\MS}_1}X^{x_{L,\MS_0}z_{L,\MS_1}}\widetilde{M}'_{\theta,f,k,L}X^{x_{L,\MS_\bot}}Z^{z_{L,\MS_\bot},z_{L,\MS_0},x_{L,\MS_1}}H^{\widetilde{\MS}_1}E^{\otimes n}_{S,\Delta}L\\
&=\LinEval_L^\dagger H^{\widetilde{\MS}_1}X^{x_{L,\MS_\bot},x_{L,\MS_0},z_{L,\MS_1}}Z^{z_{L,\MS_\bot},z_{L,\MS_0},x_{L,\MS_1}}\widetilde{M}'_{\theta,f,k,L}H^{\widetilde{\MS}_1}E^{\otimes n}_{S,\Delta}L\\
&=\LinEval_L^\dagger X^{x_L}Z^{z_L}H^{\widetilde{\MS}_1}\widetilde{M}'_{\theta,f,k,L}H^{\widetilde{\MS}_1}E^{\otimes n}_{S,\Delta}L\\
&=\LinEval_L^\dagger X^{x_L}Z^{z_L}H^{\widetilde{\MS}_1}\widetilde{M}'_{\theta,f,k,L}\left(E_{S,\Delta}^{\otimes |\MS_\bot \cup \MS_0|} \otimes E_{\widehat{S},\widehat{\Delta}}^{\otimes |\MS_1|}\right)H^{\MS_1}L \tag{\cref{claim:Hadamard}}\\
&=\LinEval_L^\dagger X^{x_L}Z^{z_L}H^{\widetilde{\MS}_1}\left(E_{S,\Delta}^{\otimes |\MS_\bot \cup \MS_0|} \otimes E_{\widehat{S},\widehat{\Delta}}^{\otimes |\MS_1|}\right)M'_{\theta,f}H^{\MS_1}L \\
&=\LinEval_L^\dagger X^{x_L}Z^{z_L}E^{\otimes n}_{S,\Delta}H^{\MS_1}M'_{\theta,f}H^{\MS_1}L \\
&=X^xZ^z\LinEval_L^\dagger E^{\otimes n}_{S,\Delta}M_{\theta,f}L\\
&=X^xZ^z E^{\otimes n}_{S,\Delta}L^\dagger M_{\theta,f}L\\
&=\Enc_{k}L^\dagger M_{\theta,f}L.
\end{align*}
\endgroup

\end{proof}
